pub fn keyFromByte(byte: u8) Key {
        if (((byte >= 32) and (byte <= 126))) {
            return Key{ .char = byte };
        }
        return (switch (byte) {
1 => .ctrl_a,
2 => .ctrl_b,
3 => .ctrl_c,
4 => .ctrl_d,
5 => .ctrl_e,
6 => .ctrl_f,
11 => .ctrl_k,
12 => .ctrl_l,
14 => .ctrl_n,
16 => .ctrl_p,
18 => .ctrl_r,
20 => .ctrl_t,
21 => .ctrl_u,
23 => .ctrl_w,
8, 127 => .backspace,
9 => .tab,
10, 13 => .enter,
27 => .escape,
else => .unknown,
});
}

