pub fn cmdEditor(repl: *Repl, _: []const u8) ReplResult {
        if (repl.in_multiline) {
            return .skip_eval;
        }
        _ = repl.print("{s}// Entering editor mode (Ctrl+D to finish, Ctrl+C to cancel){s}\n", .{ Color.dim, Color.reset });
        repl.editor_mode = true;
        _ = repl.editor_buffer.clearRetainingCapacity();
        return .skip_eval;
}

pub fn cmdBreak(repl: *Repl, _: []const u8) ReplResult {
        _ = repl.line_editor.clear();
        _ = repl.multiline_buffer.clearRetainingCapacity();
        repl.in_multiline = false;
        return .skip_eval;
}

pub fn cmdHistory(repl: *Repl, _: []const u8) ReplResult {
        _ = repl.print("\n{s}Command History:{s}\n", .{ Color.bold, Color.reset });
        const start = (if ((repl.history.entries.items.len > 20)) (repl.history.entries.items.len - 20) else 0);
